-- Egypt Top Light — Egypt in Reverse (client: Pam Witcraft, 3 guests) — OPTION B
-- 14 days / 13 nights · 27 July - 9 August 2027
-- Hurghada 5n (5* AI) -> road to Luxor 1n (4*) -> 4-night cruise Luxor->Aswan (Mon 2 Aug check-in)
-- -> Abu Simbel by road on Fri 6 Aug -> flight to Cairo -> Cairo 3n (4*)
-- ECLIPSE 2 AUGUST AT KARNAK, the morning of embarkation. PRICING LEFT BLANK.

insert into q_package_docs (name, group_ref, pax, arrival_date, departure_date, data, created_by, slug)
values ('Egypt in Reverse — the Red Sea, the Eclipse & the Nile', 'Pam Witcraft', 3, '2027-07-27', '2027-08-09',
  $pkg${"title": "Egypt in Reverse — the Red Sea, the Eclipse & the Nile", "intro": "The same fortnight, run the other way round. You land and go straight to the Red Sea, so the first five nights are all-inclusive and nothing is asked of you while the jet lag wears off. Then the road north to Luxor, and on 2 August you watch totality from Karnak before boarding — the four-night cruise begins that same Monday afternoon and carries you upstream through Esna, Edfu and Kom Ombo to Aswan, with the west bank, a cooking class and Philae along the way. Abu Simbel comes on the morning you disembark, then the flight north and three nights in Cairo for the Giza Plateau, the Grand Egyptian Museum and the Royal Mummies. Private guide and vehicle throughout, never a group.", "hero": "luxor-aswan/nile.jpeg", "meta": {"ref": "", "pax": 3, "arrival": "2027-07-27", "departure": "2027-08-09"}, "overview": {"days": 14, "nights": 13, "cities": 4}, "hotels": [{"nights": 5, "destination": "Hurghada"}, {"nights": 1, "destination": "Luxor"}, {"nights": 4, "destination": "Nile Cruise"}, {"nights": 3, "destination": "Cairo & Giza"}], "arrival": {"on": true, "title": "Arrival & Straight to the Red Sea — Tuesday 27 July", "description": "Arrival at Cairo International Airport, met airside by our representative, who stays with you through the visa, passport and customs formalities.\nStraight on to Hurghada the same day — the short connecting flight where the timings allow, otherwise by private air-conditioned vehicle.\nCheck-in at your Red Sea resort on an all-inclusive basis.\nNothing whatsoever on the schedule. Eat, swim, sleep off the flight — the sightseeing does not start for five days, which is the whole point of running the trip this way.\nOvernight in Hurghada.", "photo": "red-sea/hurghada-signs.jpeg", "meals": {"breakfast": false, "lunch": false, "dinner": true}, "hotel": "Jaz Aquamarine Hurghada, 5★ (or equal) — all-inclusive"}, "days": [{"uid": "rev-d02-hurghada-reefs", "title": "Hurghada — the Reefs & Giftun Island — Wednesday 28 July", "description": "Breakfast at the resort, and from here the pace is entirely yours: everything below is offered, nothing is compulsory.\nOptional today, at extra cost: Giftun Island and the national park reefs, the best snorkelling within reach of Hurghada — two or three stops, equipment and a guide in the water, lunch on board.\nThe dive centre can arrange an introductory dive with an instructor for anyone who would rather go under properly.\nOtherwise the private beach, the pools, the house reef and the spa, all included.\nDinner at the resort. Overnight in Hurghada.", "photo": "red-sea/coral-reefs.jpeg", "sites": ["Optional: Giftun Island", "Optional: introductory dive", "All-inclusive resort day"], "guide": false, "meals": {"breakfast": true, "lunch": true, "dinner": true}, "hotel": "Jaz Aquamarine Hurghada, 5★ (or equal) — all-inclusive"}, {"uid": "rev-d03-hurghada-orange-island", "title": "Hurghada — Orange Island & the Dolphin Banks — Thursday 29 July", "description": "Breakfast at the resort.\nOptional today, at extra cost: a full-day boat out to Orange Island, the sandbank lagoon off Hurghada with its long wooden jetty and shallow turquoise water.\nTwo swim stops over the reefs with equipment provided, and dolphin watching at the offshore banks where spinner pods gather through the morning — wild sightings, so never guaranteed.\nLunch served on board, back to the resort mid-afternoon.\nDinner at the resort. Overnight in Hurghada.", "photo": "red-sea/white-island.jpeg", "sites": ["Optional: Orange Island", "Dolphin watching", "All-inclusive resort day"], "guide": false, "meals": {"breakfast": true, "lunch": true, "dinner": true}, "hotel": "Jaz Aquamarine Hurghada, 5★ (or equal) — all-inclusive"}, {"uid": "rev-d04-hurghada-desert", "title": "Hurghada — the Eastern Desert, or Nothing at All — Friday 30 July", "description": "Breakfast at the resort.\nOptional, at extra cost: an afternoon in the Eastern Desert — quad bikes or a 4x4 out across the flats toward the Red Sea mountains, a Bedouin settlement, a camel ride if you want one, and dinner under the stars.\nOptional instead: a submarine or glass-bottom boat over the coral gardens, with no swimming needed.\nOr nothing at all. The resort is all-inclusive and the day costs you nothing extra spent on a sunbed.\nOvernight in Hurghada.", "photo": "red-sea/camels-sea.jpeg", "sites": ["Optional: desert safari & Bedouin dinner", "Optional: submarine trip", "At leisure"], "guide": false, "meals": {"breakfast": true, "lunch": true, "dinner": true}, "hotel": "Jaz Aquamarine Hurghada, 5★ (or equal) — all-inclusive"}, {"uid": "rev-d05-hurghada-leisure", "title": "Hurghada at Leisure — Saturday 31 July", "description": "Your last full day on the coast, and deliberately empty.\nBreakfast whenever you surface, then the beach, the pools, the spa, or the Marina promenade and the old town in the evening.\nA good day to rest properly: the next ten days are the busy half of this trip, and it starts tomorrow.\nDinner at the resort. Overnight in Hurghada.", "photo": "red-sea/red-sea-hotels.jpeg", "sites": ["At leisure", "All-inclusive"], "guide": false, "meals": {"breakfast": true, "lunch": true, "dinner": true}, "hotel": "Jaz Aquamarine Hurghada, 5★ (or equal) — all-inclusive"}, {"uid": "rev-d06-drive-to-luxor", "title": "Across the Desert to Luxor — Sunday 1 August", "description": "Breakfast and check-out, then west across the Eastern Desert to Luxor by private air-conditioned vehicle — roughly four hours, with comfort stops as you need them.\nWe travel today rather than tomorrow on purpose. Eclipse morning in Luxor is no time to be on a road, and arriving the night before means you wake up already where you need to be.\nCheck-in at your Luxor hotel, and the afternoon at leisure — the pool, or the corniche in the last of the light.\nYour Egyptologist meets you this evening to walk through exactly how tomorrow will run.\nAn early night. Overnight in Luxor.", "photo": "luxor-aswan/luxorpath.jpeg", "sites": ["Hurghada – Luxor by road", "Afternoon at leisure", "Eclipse briefing"], "guide": true, "meals": {"breakfast": true, "lunch": false, "dinner": false}, "hotel": "Luxor hotel, 4★ (or equal) — bed & breakfast"}, {"uid": "rev-d07-eclipse-embark-east-bank", "title": "Totality at Karnak, then Embarkation — Monday 2 August", "description": "An early breakfast and the short run to Karnak, well before the approaches close.\nYou are in the precinct of Amun for the eclipse: shade rigged, cold water, and your guide with you. The partial phases run for over an hour, the light goes wrong, the birds stop — then totality, over the temple of Amun-Ra. Luxor lies close to the point of greatest duration on this eclipse, one of the longest of the century.\nThen to the mooring: check-in with a welcome from the front office team and a quick orientation of the boat, and lunch in the main restaurant to charge your energy.\nThe afternoon begins your exploration properly — the East Bank with your Egyptologist, Karnak seen at leisure now the crowd has gone, and Luxor Temple with the standing obelisk of Ramses II at the gate.\nBack aboard for a luxury à la carte dinner, then a tanoura performance, a folklore show and live music in the lounge.\nOvernight in Luxor.", "photo": "luxor-aswan/hypostyle.jpeg", "sites": ["Total eclipse at Karnak", "Check-in & orientation", "Karnak", "Luxor Temple", "Tanoura & folklore show"], "guide": true, "meals": {"breakfast": true, "lunch": true, "dinner": true}, "hotel": "Sonesta Nile cruise, 5★ (or equal) — full board"}, {"uid": "rev-d08-west-bank-esna-edfu", "title": "The West Bank, then Sailing to Esna & Edfu — Tuesday 3 August", "description": "A gourmet breakfast buffet, then your Egyptologist takes you across to the west bank: the Valley of the Kings, its royal tombs cut deep into the hillside with painted corridors and star-vaulted ceilings intact, and the Temple of Queen Hatshepsut, three colonnaded terraces built into the cliff face.\nThe famed Colossi of Memnon as you come back on board.\nLunch in the main restaurant with the view going by, as the ship sails for Esna and then Edfu.\nTea time in the afternoon, watching the sunset in the fresh air on deck.\nThe crew will invite you for a drink in the lounge bar with live music in the background, and the à la carte dinner is waiting in the main restaurant.\nOvernight in Edfu.", "photo": "luxor-aswan/colossi.jpeg", "sites": ["Valley of the Kings", "Temple of Hatshepsut", "Colossi of Memnon", "Esna lock"], "guide": true, "meals": {"breakfast": true, "lunch": true, "dinner": true}, "hotel": "Sonesta Nile cruise, 5★ (or equal) — full board"}, {"uid": "rev-d09-edfu-cooking-kom-ombo", "title": "Edfu, a Cooking Class & Kom Ombo — Wednesday 4 August", "description": "An open buffet breakfast with the view, then Edfu Temple once you arrive, reached by horse carriage from the mooring — the most completely preserved temple in Egypt, with its black granite falcon and the roofed sanctuary still holding the barque shrine.\nBack aboard to find the executive chef waiting for you: a cooking class, and an Egyptian dish or two you can reproduce at home.\nLunch after it, a spread of properly cooked oriental dishes.\nThe afternoon on the top deck as the ship sails — ice cream, then a cup of tea in the golden light.\nIn the evening, Kom Ombo Temple: the only double temple in Egypt, halved precisely between Sobek the crocodile and Haroeris the elder Horus. Then back for the barbecue open buffet, a wide spread of charcoal grills, followed by a galabia party and live music in the lounge.\nOvernight in Aswan.", "photo": "luxor-aswan/kom-ombo.jpeg", "sites": ["Temple of Horus, Edfu", "Cooking class", "Kom Ombo Temple", "Barbecue & galabia party"], "guide": true, "meals": {"breakfast": true, "lunch": true, "dinner": true}, "hotel": "Sonesta Nile cruise, 5★ (or equal) — full board"}, {"uid": "rev-d10-high-dam-philae", "title": "Aswan — the High Dam & Philae — Thursday 5 August", "description": "The open buffet breakfast in the glamorous morning light, and a slow start: nothing is asked of you until the afternoon.\nLunch in the main restaurant.\nThen out to explore: the Aswan High Dam and the granite quarries, and the Temple of Philae, reached by motorboat to Agilkia Island — cut into blocks and rebuilt stone by stone to save it from the rising water, the last temple in Egypt where the old religion was practised.\nBack aboard for a fancy à la carte dinner, followed by oriental music and a tanoura performance in the lounge bar.\nAn early night: tomorrow starts before dawn. Overnight in Aswan.", "photo": "luxor-aswan/aswan-temple.jpeg", "sites": ["Aswan High Dam", "Philae Temple by motorboat", "Oriental music & tanoura"], "guide": true, "meals": {"breakfast": true, "lunch": true, "dinner": true}, "hotel": "Sonesta Nile cruise, 5★ (or equal) — full board"}, {"uid": "rev-d11-abu-simbel-to-cairo", "title": "Abu Simbel, then North to Cairo — Friday 6 August", "description": "Breakfast with the Nile view, then check out after breakfast; your luggage travels with the vehicle for the rest of the day.\nAbu Simbel by road, around three hours each way across the desert. Two temples cut whole into the cliff for Ramses II and Nefertari — four twenty-metre seated colossi at the facade, the Battle of Kadesh across the inner walls, and a sanctuary the entire mountain was sliced into blocks and lifted clear of the rising lake.\nYou are there in the morning light, which is when it is on the facade.\nThe drive back north to Aswan, then the flight up to Cairo, met on arrival and transferred to your hotel.\nThe evening is yours; your host can suggest somewhere to eat, or the hotel will.\nOvernight in Cairo.", "photo": "luxor-aswan/abusimbel.jpeg", "sites": ["Abu Simbel", "Ramses II & Nefertari", "Flight to Cairo"], "guide": true, "meals": {"breakfast": true, "lunch": true, "dinner": false}, "hotel": "Pyramids Park Resort Cairo, 4★ (or equal) — bed & breakfast"}, {"uid": "rev-d12-giza-gem", "title": "The Giza Plateau & the Grand Egyptian Museum — Saturday 7 August", "description": "Breakfast at the hotel, then meet your Cairo Egyptologist.\nThe Giza Plateau: the Great Pyramid of Khufu, the pyramids of Khafre and Menkaure, and the panoramic viewpoint where all three line up at once. Entry into a burial chamber is available on the spot, at extra cost.\nThe Great Sphinx and the Valley Temple of Khafre, where the causeway ends in limestone blocks the size of a small car.\nLunch at a local restaurant overlooking the plateau.\nThe Grand Egyptian Museum: the hanging obelisk, the Ramses II atrium, the grand staircase of royal statuary, and the complete Tutankhamun collection shown together for the first time — over five thousand objects with the death mask among them.\nBack to the hotel; evening at leisure. Overnight in Cairo.", "photo": "cairo-giza/gem-pyramids.jpeg", "sites": ["Great Pyramid of Khufu", "Great Sphinx", "Grand Egyptian Museum"], "guide": true, "meals": {"breakfast": true, "lunch": true, "dinner": false}, "hotel": "Pyramids Park Resort Cairo, 4★ (or equal) — bed & breakfast"}, {"uid": "rev-d13-nmec-old-cairo", "title": "Egyptian Civilization, Coptic & Islamic Cairo — Sunday 8 August", "description": "Breakfast, then the National Museum of Egyptian Civilization at Fustat: one gallery running the whole length of Egypt, and below it the Royal Mummies Hall — twenty kings and queens in low light and climate control, Ramses II and Hatshepsut among them.\nLunch at a local restaurant.\nCoptic Old Cairo on foot: the Hanging Church on the towers of the Roman fortress, the Church of St Sergius, and the Ben Ezra Synagogue — three faiths inside two hundred metres.\nAl-Moez Ldin Allah Street, the open-air museum of medieval Cairo, ending in Khan El-Khalili for mint tea at El-Fishawy among the coppersmiths and the spice sellers.\nMemphis and Sakkara, or a day in Alexandria, can be swapped in for this day instead — just say which you would rather have.\nOvernight in Cairo.", "photo": "cairo-giza/civilization-museum.jpg", "sites": ["NMEC, Fustat", "Royal Mummies Hall", "Hanging Church", "Al-Moez Street", "Khan El-Khalili"], "guide": true, "meals": {"breakfast": true, "lunch": true, "dinner": false}, "hotel": "Pyramids Park Resort Cairo, 4★ (or equal) — bed & breakfast"}], "departure": {"on": true, "title": "Departure — Monday 9 August", "description": "Breakfast at the hotel, subject to your flight timing; a breakfast box is arranged for an early departure.\nCheck-out, with a late check-out requested where the hotel can give it.\nPrivate air-conditioned transfer to Cairo International Airport in good time, with final meet & assist through check-in.\nSafe journey home.", "photo": "arrivedepart/departure-plane.jpg", "meals": {"breakfast": true, "lunch": false, "dinner": false}, "hotel": ""}, "pp": 0, "sgl": 0, "showPrice": false, "priceTableOn": false, "priceRows": [], "priceColumns": "all", "roomBasis": "double/twin", "flights": [], "category": "other", "included": "Meet & assist by our representative at every airport on arrival, departure and both domestic flights\n13 nights for three guests — 5 nights Hurghada (all-inclusive), 1 night Luxor (bed & breakfast), 4 nights aboard the Nile cruise (full board) and 3 nights Cairo & Giza (bed & breakfast)\n5★ on the Red Sea and on the Nile cruise, 4★ in Luxor and Cairo: Jaz Aquamarine Hurghada, the Sonesta Nile cruise and Pyramids Park Resort Cairo, or equal\nCairo – Hurghada on arrival day and Aswan – Cairo on Friday 6 August, with all airport transfers\nHurghada – Luxor by private air-conditioned vehicle on Sunday 1 August, travelling the day before the eclipse rather than the morning of it\nFour-night Nile cruise Luxor to Aswan to the vessel's own programme — the East Bank on the Monday; the west bank, Esna and Edfu on the Tuesday; Edfu by horse carriage, the chef's cooking class and Kom Ombo on the Wednesday; the High Dam and Philae by motorboat on the Thursday — with the tanoura and folklore show, the lounge live music, the barbecue open buffet and the galabia party all as scheduled\nEclipse-day arrangements at Karnak on 2 August: early access before the approaches close, shade and cold water for all three guests, and your guide with you throughout\nAbu Simbel by road on Friday 6 August, straight off the boat — roughly three hours each way across the desert in a private air-conditioned vehicle, or optionally by short flight instead of the drive, at a supplement\nPrivate air-conditioned vehicle for every transfer and excursion, at your disposal alone — never shared, no group at any point\nPrivate licensed Egyptologist guide on every sightseeing day in Luxor, on the cruise, at Abu Simbel and in Cairo\nEntrance fees to every site named in the programme, including Karnak, Luxor Temple, the Valley of the Kings, Hatshepsut, Edfu, Kom Ombo, Philae, the High Dam, Abu Simbel, the Giza Plateau, the Grand Egyptian Museum and the NMEC with the Royal Mummies Hall\nFull all-inclusive at the Red Sea resort, full board throughout the cruise, and all meals as specified elsewhere\nBottled water in the vehicle throughout\nAll local taxes and service charges\n24/7 support from our Cairo office for the whole fourteen days\nWritten booking confirmation setting out the payment schedule and cancellation terms in full before any deposit is taken", "excluded": "International airfare to and from Egypt — book early; eclipse-week seats and beds are already scarce\nEgypt entry visa (USD 36, payable on arrival)\nAny special eclipse-day surcharge set by the Ministry of Tourism & Antiquities on admission to Karnak — not published at the time of quoting, and confirmed in writing as soon as it is\nThe optional Hurghada excursions named in the programme — Giftun Island, Orange Island, the desert safari, diving and the submarine — all bookable locally\nOptional entry inside the Great Pyramid at Giza, and the separately ticketed tombs of Tutankhamun, Seti I and Nefertari\nOptional sunrise hot-air balloon over the Luxor west bank\nLunches and dinners in Cairo and Luxor other than those listed\nDrinks with meals outside the all-inclusive resort, and anything from the ship's bar\nSpa treatments and anything booked directly with the hotel, ship or resort\nTravel insurance\nTipping and gratuities for the guides, drivers and ship crew\nPersonal expenses, laundry and telephone calls\nAnything not listed under \"Included\""}$pkg$::jsonb,
  '0a58da13-831c-4322-8f62-e5777cc5f2b7',
  'egypt-in-reverse-the-red-sea-the-eclipse-and-the-nile');
